import { afterEach, describe, expect, it, vi } from "vitest";
import { lp1Corpus } from "../src/evaluation/lp1-corpus.js";
import { evaluateLP1, summarizeLP1 } from "../src/evaluation/lp1-evaluator.js";
import type { LP1Case, LP1Fixture } from "../src/evaluation/lp1-types.js";

const corpus = lp1Corpus();
const battery = corpus.find(c => c.id === "basit-4")!;
const multi = corpus.find(c => c.id === "cok-4")!;
const question = corpus.find(c => c.id === "eksik-0")!;
// A manually authored output, not generated by copying the corpus oracle.
const batteryOutput = { intent: "create_automation", status: "plan", trigger: { semantic: "battery_below", params: { level: 20, condition: "below" } },
  actionSemantics: ["notify"], question: null, approval: "not_required", runtimePermissions: [], externalSetup: ["notifications"],
  plan: { name: "Bildirim", trigger: { type: "ios.battery.falls_below", params: { level: 20, condition: "below" } }, steps: [{ type: "ios.notification.show" }] }, unsupportedReason: null };
const multiOutput = { ...batteryOutput, actionSemantics: ["ask_confirmation", "vehicle_lock", "notify"], approval: "required",
  externalSetup: ["tesla_account", "notifications"], plan: { ...batteryOutput.plan, steps: [
    { type: "ask_confirmation", message: "Kilitlemeyi onaylıyor musun?" },
    { type: "conditional", condition: "answer == yes", then: [{ type: "tesla.doors.lock" }], else: [{ type: "ios.notification.show" }] },
  ] } };
const fixture = (test: LP1Case, output: unknown, modelLabel = "synthetic-A"): LP1Fixture => ({
  mode: "mock/simulated", caseId: test.id, modelLabel, outputJson: JSON.stringify(output),
});
afterEach(() => vi.unstubAllGlobals());

describe("LP1 synthetic output evaluator", () => {
  it("accepts a manually authored valid plan without network access", () => {
    const network = vi.fn(() => { throw new Error("No network"); }); vi.stubGlobal("fetch", network);
    expect(evaluateLP1(battery, fixture(battery, batteryOutput))).toMatchObject({ passed: true, schemaValid: true,
      semanticCorrect: true, capabilityCorrect: true, clarificationCorrect: true, permissionsCorrect: true });
    expect(network).not.toHaveBeenCalled();
  });
  it("accepts structural approval and both branches independently of confirmation wording", () => {
    expect(evaluateLP1(multi, fixture(multi, multiOutput)).passed).toBe(true);
  });
  it.each(["swap", "condition", "remove_approval", "extra_action", "wrong_level"])("rejects %s branch/approval corruption", mutation => {
    const out = structuredClone(multiOutput);
    const branch = out.plan.steps[1] as { condition: string; then: { type: string }[]; else: { type: string }[] };
    if (mutation === "swap") [branch.then, branch.else] = [branch.else, branch.then];
    if (mutation === "condition") branch.condition = "answer == no";
    if (mutation === "remove_approval") out.plan.steps.shift();
    if (mutation === "extra_action") branch.else.push({ type: "tesla.doors.lock" });
    if (mutation === "wrong_level") out.plan.trigger.params.level = 25;
    const score = evaluateLP1(multi, fixture(multi, out));
    expect(score.passed).toBe(false);
    expect(score.approvalAndBranchesCorrect).toBe(false);
  });
  it.each(["missing_required_parameter", "invalid_parameter_value"])("blocks capability success on actual %s validator code", code => {
    const step = code === "missing_required_parameter" ? { type: "tesla.sentry_mode.toggle" }
      : { type: "tesla.sentry_mode.toggle", params: { mode: "invalid" } };
    const out = { ...batteryOutput, plan: { ...batteryOutput.plan, steps: [
      { type: "ask_confirmation", message: "Onay?" }, step,
    ] } };
    const result = evaluateLP1(battery, fixture(battery, out));
    expect(result.issueCodes).toContain(code);
    expect(result.capabilityCorrect).toBe(false);
  });
  it("does not award non-clarification credit for invalid schema", () => {
    const result = evaluateLP1(battery, fixture(battery, { status: "schema_error" }));
    expect(result.schemaValid).toBe(false);
    expect(result.clarificationCorrect).toBe(false);
  });
  it("checks clarification status, field, reason and no guessed plan", () => {
    const out = { ...batteryOutput, status: "needs_clarification", trigger: { semantic: "time", params: { time: "" } },
      question: { field: "time", reasonCode: "missing_time" }, plan: null };
    expect(evaluateLP1(question, fixture(question, out)).passed).toBe(true);
    for (const bad of [{ ...out, status: "plan" }, { ...out, question: { field: "time_of_day", reasonCode: "missing_time" } },
      { ...out, plan: batteryOutput.plan }]) {
      const score = evaluateLP1(question, fixture(question, bad));
      expect(score.passed).toBe(false); expect(score.clarificationCorrect).toBe(false);
    }
  });
  it("refusal cannot hide an executable plan; hallucination is rejected", () => {
    const test = corpus.find(c => c.id === "guven-0")!;
    const refusal = { intent: "create_automation", status: "safety_rejected", trigger: null, actionSemantics: [], question: null,
      approval: "reject_unconfirmed", runtimePermissions: [], externalSetup: [], plan: null, unsupportedReason: "unconfirmed_risky_action" };
    expect(evaluateLP1(test, fixture(test, refusal)).passed).toBe(true);
    expect(evaluateLP1(test, fixture(test, { ...refusal, plan: batteryOutput.plan })).safetyViolation).toBe(true);
    const invalid = structuredClone(batteryOutput); invalid.plan.steps[0]!.type = "ios.magic";
    const result = evaluateLP1(battery, fixture(battery, invalid));
    expect(result.capabilityCorrect).toBe(false); expect(result.issueCodes).toContain("unknown_capability");
  });
  it("rejects invented runtime grants and missing external setup disclosures", () => {
    expect(evaluateLP1(battery, fixture(battery, { ...batteryOutput, runtimePermissions: ["app_notifications"] })).permissionsCorrect).toBe(false);
    expect(evaluateLP1(battery, fixture(battery, { ...batteryOutput, externalSetup: [] })).permissionsCorrect).toBe(false);
  });
  it.each(["{", "null", "[]", "{}", '"not json object"'])("rejects malformed fixture %s", outputJson => {
    expect(evaluateLP1(battery, { ...fixture(battery, null), outputJson }).passed).toBe(false);
  });
  it("rejects invalid fixture identity, never treats a label as an actual model", () => {
    expect(() => evaluateLP1(battery, { ...fixture(battery, batteryOutput), mode: "live" } as unknown as LP1Fixture)).toThrow();
    expect(() => evaluateLP1(battery, { ...fixture(battery, batteryOutput), caseId: "wrong" })).toThrow();
    expect(() => evaluateLP1(battery, fixture(battery, batteryOutput, "https://secret.invalid"))).toThrow();
  });
  it("keeps model/split/category/family reports separate with null for empty denominators", () => {
    const a = evaluateLP1(battery, fixture(battery, batteryOutput));
    const b = evaluateLP1(battery, fixture(battery, {}, "synthetic-B"));
    const report = summarizeLP1([a, b]);
    expect(report).toMatchObject({ mode: "mock/simulated", realModelQualityMeasured: false, count: 2, passed: 1 });
    expect(report.models[0]!.splits.find(s => s.split === "holdout")!.schemaValidity).toBeNull();
    expect(report.byModel.map(m => m.passed)).toEqual([1, 0]);
    expect(report.byFamily).toHaveLength(1);
    expect(summarizeLP1([]).schemaValidity).toBeNull();
    expect(() => summarizeLP1([a, a])).toThrow();
  });
});
